        if (myArray.length == 0) {
            return new int[0]; // return an empty array if input is empty
        }

        int max = myArray[0];
        int min = myArray[0];

        for (int num : myArray) {
            if (num > max) max = num;
            if (num < min) min = num;
        }

        int range = max - min + 1;
        int[] countArray = new int[range];

        for (int i = 0; i < myArray.length; i++) {
            countArray[myArray[i] - min]++;
        }

        int index = 0;
