            break;
        case 1:
            input = "";
            break;
        case 2:
            input = "   ";
            break;
        case 3:
            input = randomWord(random, random.nextInt(6) * 2 + 1); // odd length
            break;
        case 4:
            input = randomWord(random, random.nextInt(6) * 2 + 2); // even length
            break;
        case 5: {
            // multiple words, all odd
            int wordCount = random.nextInt(5) + 1;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) sb.append(' ');
                sb.append(randomWord(random, random.nextInt(5) * 2 + 1));
            }
            input = sb.toString();
            break;
        }
        case 6: {
            // multiple words, all even, with increasing lengths to test tie (first wins)
            int wordCount = random.nextInt(5) + 2;
            StringBuilder sb = new StringBuilder();
            int lastLen = 0;
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) sb.append(' ');
                int len = random.nextInt(5) * 2 + 2;
                // sometimes repeat the same even length to test tie
                if (random.nextBoolean() && i > 0) len = lastLen;
                sb.append(randomWord(random, len));
                lastLen = len;
            }
            input = sb.toString();
            break;
        }
        case 7: {
            // mix of odd and even, with unique longest even
            int wordCount = random.nextInt(5) + 2;
            StringBuilder sb = new StringBuilder();
            int maxEvenLen = 0;
            int maxEvenIndex = -1;
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) sb.append(' ');
                boolean isEven = random.nextBoolean();
                int len;
                if (isEven) {
                    len = random.nextInt(5) * 2 + 2;
                    if (len > maxEvenLen) {
                        maxEvenLen = len;
                        maxEvenIndex = i;
                    }
                } else {
                    len = random.nextInt(5) * 2 + 1;
                }
                sb.append(randomWord(random, len));
            }
            // ensure at least one even word (if maxEvenIndex == -1, force one)
            if (maxEvenIndex == -1) {
                sb.append(' ').append(randomWord(random, random.nextInt(5) * 2 + 2));
            }
            input = sb.toString();
            break;
        }
        case 8: {
            // leading/trailing spaces
            int wordCount = random.nextInt(3) + 1;
            StringBuilder sb = new StringBuilder();
            sb.append(' '); // leading
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) sb.append(' ');
                sb.append(randomWord(random, random.nextInt(5) * 2 + 1)); // odd
                sb.append(' ');
            }
            sb.append(' '); // trailing
            input = sb.toString();
            break;
        }
        case 9: {
            // multiple spaces between words
            int wordCount = random.nextInt(3) + 2;
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < wordCount; i++) {
                if (i > 0) {
                    int spaces = random.nextInt(3) + 2; // 2-4 spaces
                    for (int s = 0; s < spaces; s++) sb.append(' ');
                }
                sb.append(randomWord(random, random.nextInt(5) * 2 + 2)); // even
            }
            input = sb.toString();
            break;
        }
        default:
            input = "test";
            break;
    }
    return new Object[]{input};
}

private static String randomWord(Random random, int length) {
    if (length <= 0) return "";
    StringBuilder sb = new StringBuilder(length);
    for (int i = 0; i < length; i++) {
        char c = (char) ('a' + random.nextInt(26));
        sb.append(c);
    }
    return sb.toString();
}

