    int prev1 = Integer.MIN_VALUE / 2;
    for (int i = 0; i < m; i++) {
        prev1 += random.nextInt(5) + 1; // strictly increasing
        arr1[i] = prev1;
    }
    int prev2 = Integer.MIN_VALUE / 2;
    for (int i = 0; i < n; i++) {
        prev2 += random.nextInt(5) + 1;
        arr2[i] = prev2;
    }

    // Occasionally make arrays empty
    if (random.nextBoolean() && m > 0) {
        arr1 = new int[0];
        m = 0;
    }
    if (random.nextBoolean() && n > 0) {
        arr2 = new int[0];
        n = 0;
    }

    // Occasionally use extreme values
    if (random.nextInt(5) == 0 && m > 0) {
        arr1[0] = Integer.MIN_VALUE;
        arr1[m-1] = Integer.MAX_VALUE;
    }
    if (random.nextInt(5) == 0 && n > 0) {
        arr2[0] = Integer.MIN_VALUE;
        arr2[n-1] = Integer.MAX_VALUE;
    }

    // Ensure k is valid: 1 <= k <= m+n (or 0 if both empty, but avoid invalid)
