    // Decide which scenario to generate
    int scenario = random.nextInt(7);
    String[] arr;

    switch (scenario) {
        case 0:
            // null array
            arr = null;
            break;
        case 1:
            // empty array
            arr = new String[0];
            break;
        case 2:
            // single element array
            arr = new String[]{generateRandomString(random, random.nextInt(10))};
            break;
        case 3:
            // all same elements (multiple)
            int len = random.nextInt(5) + 2; // 2 to 6
            String base = generateRandomString(random, random.nextInt(10));
            arr = new String[len];
            for (int i = 0; i < len; i++) {
                arr[i] = base;
            }
            break;
        case 4:
            // all different elements (no duplicates)
            len = random.nextInt(5) + 2;
            arr = new String[len];
            for (int i = 0; i < len; i++) {
                String s;
                // Ensure uniqueness
                do {
                    s = generateRandomString(random, random.nextInt(10));
                } while (contains(arr, i, s));
                arr[i] = s;
            }
            break;
        case 5:
            // mixed: some equal, some different, possibly null elements
            len = random.nextInt(5) + 3; // 3 to 7
            arr = new String[len];
            // Fill first half with same string
            String same = generateRandomString(random, random.nextInt(10));
            int half = len / 2;
            for (int i = 0; i < half; i++) {
                arr[i] = same;
            }
            // Fill rest with random strings or null
            for (int i = half; i < len; i++) {
                if (random.nextBoolean()) {
                    arr[i] = generateRandomString(random, random.nextInt(10));
                } else {
                    arr[i] = null; // null element
                }
            }
            break;
        case 6:
            // array with null elements only (all null)
            len = random.nextInt(4) + 1; // 1 to 4
            arr = new String[len];
            for (int i = 0; i < len; i++) {
                arr[i] = null;
            }
            break;
        default:
            // Should not happen
            arr = new String[]{"default"};
            break;
    }

    return new Object[]{arr};
}

private static String generateRandomString(Random random, int length) {
    // Generate a random string of printable ASCII characters (32-126)
    // Allow empty string (length 0)
    StringBuilder sb = new StringBuilder(length);
    for (int i = 0; i < length; i++) {
        char c = (char) (random.nextInt(95) + 32); // 32 to 126 inclusive
        sb.append(c);
    }
    return sb.toString();
}

// Helper to check if a string is already in the array up to index
private static boolean contains(String[] arr, int upTo, String s) {
    for (int i = 0; i < upTo; i++) {
        if (arr[i] != null && arr[i].equals(s)) {
            return true;
        }
        if (arr[i] == null && s == null) {
            return true;
        }
    }
    return false;
}

