            testTup1 = null;
            testTup2 = null;
            break;
        case 4: // Different sizes (first longer, second shorter)
            int size1 = random.nextInt(5) + 2; // at least 2
            int size2 = random.nextInt(size1); // smaller than size1
            testTup1 = generateRandomList(random, size1);
