            }
            break;
        case 8: // One-element lists
            testTup1 = new ArrayList<>();
            testTup2 = new ArrayList<>();
            testTup1.add(random.nextInt());
            testTup2.add(random.nextInt());
            break;
        case 9: // Lists with negative values
            int negSize = random.nextInt(4) + 1;
            testTup1 = new ArrayList<>();
