public static Object[] generateValidInput(Random random) {
    // Decide which type of input to generate
    int mode = random.nextInt(6);
    String str = null;
    switch (mode) {
        case 0:
            // Empty string
            str = "";
            break;
        case 1:
            // Single character
            str = String.valueOf((char) ('a' + random.nextInt(26)));
            break;
        case 2:
            // All characters are the same (no non-repeating)
            int len = random.nextInt(10) + 2; // at least 2
            char ch = (char) ('a' + random.nextInt(26));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < len; i++) {
                sb.append(ch);
            }
            str = sb.toString();
            break;
        case 3:
            // String with all unique characters
            int uniqueLen = random.nextInt(10) + 1;
            // Generate random permutation of distinct letters
            // Use a simple approach: pick random letters from a set
            StringBuilder sb2 = new StringBuilder();
            for (int i = 0; i < uniqueLen; i++) {
                char c;
                do {
                    c = (char) ('a' + random.nextInt(26));
                } while (sb2.indexOf(String.valueOf(c)) != -1);
                sb2.append(c);
            }
            str = sb2.toString();
            break;
        case 4:
            // String with some repeats and some non-repeating (or none)
            int totalLen = random.nextInt(10) + 2;
            StringBuilder sb3 = new StringBuilder();
            for (int i = 0; i < totalLen; i++) {
                // Randomly decide to repeat a previous character or add a new one
                if (sb3.length() > 0 && random.nextBoolean()) {
                    // Pick a random character from existing
                    int idx = random.nextInt(sb3.length());
                    sb3.append(sb3.charAt(idx));
                } else {
                    // Add a new random character
                    sb3.append((char) ('a' + random.nextInt(26)));
                }
            }
            str = sb3.toString();
            break;
        case 5:
            // Null string (boundary)
            str = null;
            break;
    }
    // Randomly with small probability, generate a longer string
    if (random.nextInt(10) == 0) {
        // Generate a longer string of length 20-50
        int longLen = random.nextInt(31) + 20;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < longLen; i++) {
            sb.append((char) ('a' + random.nextInt(26)));
        }
        str = sb.toString();
    }
    return new Object[]{str};
}

