            int idx = 0;
            while (idx < n) {
                if (idx == n - 1) {
                    arr[idx++] = oddElement;
                } else {
                    int even = random.nextInt(21) - 10;
                    if (even % 2 == 0) even++; // make odd to avoid even elements
                    arr[idx++] = even;
                    arr[idx++] = even;
                }
            }
            arrSize = n;
