    } else if (choice == 3) {
        // already sorted (not rotated)
        int size = random.nextInt(10) + 1;
        int[] arr = new int[size];
        int start = random.nextInt(100);
        for (int i = 0; i < size; i++) {
            arr[i] = start + i;
        }
        return new Object[]{arr, 0, size - 1};
    } else if (choice == 4) {
        // empty array
        return new Object[]{new int[0], 0, -1};
    } else if (choice == 5) {
        // null array
        return new Object[]{null, 0, 0};
    } else if (choice == 6) {
        // all equal values
        int val = random.nextInt(100);
        int size = random.nextInt(10) + 1;
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = val;
        }
        return new Object[]{arr, 0, size - 1};
    } else if (choice == 7) {
        // minimum at index 0
        int size = random.nextInt(10) + 2;
        int[] arr = new int[size];
        int start = random.nextInt(100);
        for (int i = 0; i < size; i++) {
            arr[i] = start + i;
        }
        return new Object[]{arr, 0, size - 1};
    } else if (choice == 8) {
        // local minimum at mid: [3,4,0,1,2] -> mid=2, arr[2]=0
        return new Object[]{new int[]{3, 4, 0, 1, 2}, 0, 4};
    } else if (choice == 9) {
        // else-if branch: [5,1,0] -> mid=1, arr[1]=1 < arr[0]=5, arr[1] >= arr[2]
        return new Object[]{new int[]{5, 1, 0}, 0, 2};
    } else if (choice == 10) {
        // random rotated sorted array, full range
        int size = random.nextInt(8) + 3;
        int[] sorted = new int[size];
        int start = random.nextInt(100);
        for (int i = 0; i < size; i++) {
            sorted[i] = start + i;
        }
        int rotation = random.nextInt(size);
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = sorted[(i + rotation) % size];
        }
        return new Object[]{arr, 0, size - 1};
    } else {
        // random rotated sorted array, random low/high subrange
        int size = random.nextInt(8) + 3;
        int[] sorted = new int[size];
        int start = random.nextInt(100);
        for (int i = 0; i < size; i++) {
            sorted[i] = start + i;
        }
        int rotation = random.nextInt(size);
        int[] arr = new int[size];
        for (int i = 0; i < size; i++) {
            arr[i] = sorted[(i + rotation) % size];
        }
        int low = random.nextInt(size);
        int high = low + random.nextInt(size - low);
        return new Object[]{arr, low, high};
    }
