            break;
        case 5: // two elements, both non-integer -> count 0
            testTup = new Object[]{ new Object(), new Object() };
            break;
        case 6: // two elements, both integers -> count 1
            testTup = new Object[]{ random.nextInt(), random.nextInt() };
            break;
        case 7: // all integers except last
            int len = random.nextInt(10) + 2;
            testTup = new Object[len];
            for (int i = 0; i < len - 1; i++) {
                int b = random.nextInt(5);
                switch (b) {
                    case 0: testTup[i] = 0; break;
                    case 1: testTup[i] = 1; break;
                    case 2: testTup[i] = -1; break;
                    case 3: testTup[i] = Integer.MAX_VALUE; break;
                    case 4: testTup[i] = Integer.MIN_VALUE; break;
                    default: testTup[i] = random.nextInt();
                }
            }
            testTup[len - 1] = new Object(); // last element not counted
            break;
        case 8: // no integers before last
            len = random.nextInt(10) + 2;
            testTup = new Object[len];
            for (int i = 0; i < len - 1; i++) {
                testTup[i] = new Object();
            }
