            break;
        case 9: // mixed with nulls and arrays
            len = random.nextInt(10) + 1;
            testTup = new Object[len];
            for (int i = 0; i < len; i++) {
                int type = random.nextInt(4);
                switch (type) {
                    case 0: testTup[i] = random.nextInt(); break;
                    case 1: testTup[i] = new Object(); break;
                    case 2: testTup[i] = null; break;
                    case 3: testTup[i] = new Object[]{ random.nextInt() }; break;
                }
            }
