                    case 1: testTup[i] = new Object(); break;
                    case 2: testTup[i] = new Object[]{ random.nextInt() }; break;
                }
            }
            break;
        case 11: // array with specific boundary values in first positions
            testTup = new Object[]{0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            break;
        case 12: // non-integer at first position, then mixed
            len = random.nextInt(5) + 2;
            testTup = new Object[len];
