    } else {
        length = 4 + random.nextInt(17); // 4..20
    }

    int[] array = new int[length];
    int strategy = random.nextInt(6);

    switch (strategy) {
        case 0:
            // All elements identical, chosen from boundary values.
            int same;
            int b = random.nextInt(5);
            if (b == 0) same = Integer.MIN_VALUE;
            else if (b == 1) same = Integer.MAX_VALUE;
            else if (b == 2) same = -1;
            else if (b == 3) same = 0;
            else same = 1;
            for (int i = 0; i < length; i++) {
                array[i] = same;
            }
            break;
        case 1:
            // Distinct elements from a broad range.
            for (int i = 0; i < length; i++) {
                int val;
                boolean duplicate;
                do {
                    val = random.nextInt(20000) - 10000;
                    duplicate = false;
                    for (int j = 0; j < i; j++) {
                        if (array[j] == val) {
                            duplicate = true;
                            break;
                        }
                    }
                } while (duplicate);
                array[i] = val;
            }
            break;
        case 2:
            // Elements from a tiny pool, causing many duplicates.
            int[] pool = {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0, 1, 100, -100, 2};
            for (int i = 0; i < length; i++) {
                array[i] = pool[random.nextInt(pool.length)];
            }
            break;
        case 3:
            // Random values mixed with boundary values every third element.
            int[] boundaries = {Integer.MIN_VALUE, Integer.MAX_VALUE, -1, 0, 1};
            for (int i = 0; i < length; i++) {
                if (i % 3 == 0) {
                    array[i] = boundaries[random.nextInt(boundaries.length)];
                } else {
                    array[i] = random.nextInt(2001) - 1000;
                }
            }
            break;
        case 4:
            // Increasing sequence, sometimes starting near overflow.
            int start;
            int s = random.nextInt(3);
            if (s == 0) start = Integer.MAX_VALUE - length;
            else if (s == 1) start = Integer.MIN_VALUE;
            else start = random.nextInt(21) - 10;
            for (int i = 0; i < length; i++) {
                array[i] = start + i;
            }
            break;
        default:
            // Decreasing sequence, sometimes starting near overflow.
            int startD;
            int ds = random.nextInt(3);
            if (ds == 0) startD = Integer.MIN_VALUE + length;
            else if (ds == 1) startD = Integer.MAX_VALUE;
            else startD = random.nextInt(21) - 10;
            for (int i = 0; i < length; i++) {
                array[i] = startD - i;
            }
            break;
    }

    return new Object[] { array };
}

