        int maxElement = Arrays.stream(arr).max().orElse(0);
        int[] countMap = new int[maxElement + 1];
        int count = 0;

        for (int num : arr) {
            if (countMap[num] > 0) {
                count += countMap[num];
                countMap[num]++;
            } else {
                countMap[num] = 1;
            }
        }

        for (int i = 0; i < countMap.length; i++) {
            if (countMap[i] > 1 && (n - i) % countMap[i] == 0) {
                return count + (n - i) / countMap[i];
            }
        }
        return count;
    }

