public static String[] wordsAe(String text) {
        String[] tempResult = new String[text.length()]; // Temporary array to hold results
        int count = 0; // Count of valid words found

        for (int i = 0; i < text.length(); i++) {
            if (text.charAt(i) == 'a' || text.charAt(i) == 'e') {
                int j = i;
                while (j < text.length() && text.charAt(j) != ' ') {
                    j++;
                }

                tempResult[count] = text.substring(i, j);
                count++;
                i = j - 1; // Move the index to the end of the current word
            }
        }

        String[] result = new String[count];
        System.arraycopy(tempResult, 0, result, 0, count);

        return result;
    }

