            str = new String[n];
            // generate strings of lengths 0..10 (excluding 7)
            for (int i = 0; i < n; i++) {
                int len;
                do {
                    len = random.nextInt(11); // 0 to 10
                } while (len == 7);
                str[i] = generateString(random, len);
            }
            l = 7; // length that does not appear
            break;
        }
        case 5: // l = 0, some empty strings
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            // At least one empty string
            int pos = random.nextInt(n);
            str[pos] = ""; // length 0
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                int len = random.nextInt(6) + 1; // 1 to 6
                str[i] = generateString(random, len);
            }
            l = 0;
            break;
        }
        case 6: // l = -1
        {
