            str = new String[n];
            for (int i = 0; i < n; i++) {
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = -1;
            break;
        }
        case 7: // l = Integer.MAX_VALUE
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            for (int i = 0; i < n; i++) {
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = Integer.MAX_VALUE;
            break;
        }
        case 8: // l = 1, some strings of length 1
        {
            int n = random.nextInt(5) + 1; // 1 to 5
            str = new String[n];
            // At least one string of length 1
            int pos = random.nextInt(n);
            str[pos] = generateString(random, 1);
            for (int i = 0; i < n; i++) {
                if (i == pos) continue;
                int len = random.nextInt(6); // 0 to 5
                str[i] = generateString(random, len);
            }
            l = 1;
            break;
        }
        default: // case 9: multiple matches of same length
        {
            int n = random.nextInt(5) + 2; // 2 to 6 strings
            str = new String[n];
            int targetLen = random.nextInt(6); // 0 to 5
            // At least two strings of target length
            int pos1 = random.nextInt(n);
            int pos2;
            do {
                pos2 = random.nextInt(n);
            } while (pos2 == pos1);
            str[pos1] = generateString(random, targetLen);
            str[pos2] = generateString(random, targetLen);
            for (int i = 0; i < n; i++) {
                if (i == pos1 || i == pos2) continue;
                int len = random.nextInt(11); // 0 to 10
                str[i] = generateString(random, len);
            }
            l = targetLen;
            break;
        }
    }

    return new Object[]{str, l};
