// Helper: generate a random string of length 0..10 using lowercase letters and spaces
private static String randomString(Random random) {
    int len = random.nextInt(11); // 0..10
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        // 50% chance of space, 50% chance of letter
        if (random.nextBoolean()) {
            sb.append(' ');
        } else {
            sb.append((char) ('a' + random.nextInt(26)));
        }
    }
    return sb.toString();
}

