    }

    if (choice == 1) {
        return new Object[]{new int[0], Integer.valueOf(0), Integer.valueOf(1)};
    }

    int size = 1 + random.nextInt(20);
    int[] arr = new int[size];

    switch (choice) {
        case 2: {
            int sameVal = random.nextInt(20) - 10;
            for (int i = 0; i < size; i++) arr[i] = sameVal;
            break;
        }
        case 3: {
            for (int i = 0; i < size; i++) arr[i] = i * 10 + random.nextInt(3);
            break;
        }
        case 4: {
            for (int i = 0; i < size; i++) arr[i] = random.nextInt(5);
            break;
        }
        case 5: {
            for (int i = 0; i < size; i++) arr[i] = i;
            break;
        }
        case 6: {
            arr[0] = Integer.MAX_VALUE;
            if (size > 1) {
                arr[size - 1] = Integer.MIN_VALUE;
                for (int i = 1; i < size - 1; i++) arr[i] = random.nextInt(200) - 100;
            }
            break;
        }
        case 7: {
            for (int i = 0; i < size; i++) {
                int r = random.nextInt(4);
                if (r == 0) arr[i] = Integer.MAX_VALUE;
                else if (r == 1) arr[i] = Integer.MIN_VALUE;
                else if (r == 2) arr[i] = 0;
                else arr[i] = random.nextInt(200) - 100;
            }
            break;
        }
        case 8: {
            int targetVal = random.nextInt(50) - 25;
            int repeats = 2 + random.nextInt(Math.min(3, size));
            for (int i = 0; i < size; i++) {
                arr[i] = (i < repeats) ? targetVal : (100 + i);
            }
            break;
        }
        case 9: {
            for (int i = 0; i < size; i++) arr[i] = i * 7 + 1;
            break;
        }
        case 10: {
            for (int i = 0; i < size; i++) arr[i] = random.nextInt(1000) - 500;
            break;
        }
        case 11: {
            int base = random.nextInt(10);
            for (int i = 0; i < size; i++) arr[i] = base + (i % 2 == 0 ? 0 : 1);
            break;
        }
        case 12: {
            int val = random.nextInt(10);
            for (int i = 0; i < size; i++) arr[i] = (i < size / 2) ? val : (val + 100 + i);
            break;
        }
        default: {
            for (int i = 0; i < size; i++) arr[i] = random.nextInt(10);
            break;
        }
    }

    int n;
    int k;

    switch (choice) {
        case 5:
            n = size;
            k = 1;
            break;
        case 8:
            n = size;
            {
                int cnt = 0;
                int first = arr[0];
                for (int i = 0; i < size; i++) if (arr[i] == first) cnt++;
                k = cnt;
            }
            break;
        case 9:
            n = size;
            k = 2 + random.nextInt(3);
            break;
        case 2:
            n = size;
            k = size;
            break;
        case 12:
            n = size;
            {
                int cnt = 0;
                int first = arr[0];
                for (int i = 0; i < size; i++) if (arr[i] == first) cnt++;
                k = cnt + 1;
            }
            break;
        default:
            n = random.nextInt(size + 1);
            int kChoice = random.nextInt(5);
            if (kChoice == 0) k = 0;
            else if (kChoice == 1) k = -1;
            else if (kChoice == 2) k = 1;
            else if (kChoice == 3) k = size + 1;
            else k = 1 + random.nextInt(size + 2);
            break;
    }

    return new Object[]{arr, Integer.valueOf(n), Integer.valueOf(k)};
}

