public static Object[] generateValidInput(Random random) {
    int choice = random.nextInt(10);
    int x, y, z;

    switch (choice) {
        case 0: // x == y == z (all equal) → first && true, short-circuit
            x = random.nextInt(10000);
            y = x;
            z = x;
            break;
        case 1: // x == y, y != z → first &&: x==y true, y==z false
            x = random.nextInt(10000);
            y = x;
            z = x + 1 + random.nextInt(100);
            break;
        case 2: // x != y, y != z, x != z (all different) → first && false (x!=y), second && false (x!=z), third && false (x!=y)
            x = random.nextInt(10000);
            y = x + 1 + random.nextInt(100);
            z = y + 1 + random.nextInt(100);
            break;
        case 3: // x == z, x != y, y != z → first && false (x!=y), second &&: x==z true, y==z false
            x = random.nextInt(10000);
            z = x;
            y = x + 1 + random.nextInt(100);
            break;
        case 4: // x == y, x != z, y != z → first && false (y!=z), second && false (x!=z), third &&: x==y true, x==z false
            x = random.nextInt(10000);
            y = x;
            z = x + 1 + random.nextInt(100);
            break;
        case 5: // y == z, x != y, x != z → first && false (x!=y), second &&: x!=z (short-circuit second &&), third &&: x!=y (short-circuit)
            y = random.nextInt(10000);
            z = y;
            x = y + 1 + random.nextInt(100);
            break;
        case 6: // boundary: all equal extremes
            int[] bounds = {0, 1, -1, Integer.MAX_VALUE, Integer.MIN_VALUE};
            x = bounds[random.nextInt(bounds.length)];
            y = x;
            z = x;
            break;
        case 7: // boundary: x==z, x!=y (evaluates second && y==z)
            x = 0; z = 0; y = 1;
            break;
        case 8: // boundary: x==y, x!=z (evaluates third && x==z)
            x = 1; y = 1; z = 0;
            break;
        default: // fully random
            x = random.nextInt();
            y = random.nextInt();
            z = random.nextInt();
            break;
    }

    return new Object[]{x, y, z};
}
